/**
 * FUI-01 — the Factory UI reference artboards in `frontend/design/factory-ui/`
 * stay static: no design-canvas runtime, a 1440×960 root frame, and no link to
 * a file that is not committed beside them (the DEvals artboard is not committed).
 *
 * The files are generated by `design/factory-ui/strip-canvas.mjs`, never
 * hand-edited.
 */
import { existsSync, readFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { describe, expect, it } from 'vitest';

const DESIGN_DIR = new URL('../../design/factory-ui/', import.meta.url);
const ARTBOARDS = ['DEpic.html', 'DWork.html', 'DMonitor.html'];

function read(name: string): string {
  return readFileSync(new URL(name, DESIGN_DIR), 'utf8');
}

function hrefs(html: string): string[] {
  return [...html.matchAll(/\shref\s*=\s*["']([^"']*)["']/gi)].map((match) => match[1]);
}

function isRelative(href: string): boolean {
  return !/^([a-z][a-z0-9+.-]*:|\/\/|#)/i.test(href);
}

describe.each(ARTBOARDS)('%s', (name) => {
  const html = read(name);

  it('carries no design-canvas runtime', () => {
    for (const marker of ['x-dc', '<helmet', 'support.js', 'data-dc-script']) {
      expect(html, marker).not.toContain(marker);
    }
  });

  it('has a 1440×960 root frame', () => {
    const body = html.match(/<body[^>]*>\s*<(\w+)([^>]*)>/);
    expect(body, 'root element after <body>').not.toBeNull();
    const style = body![2].match(/style="([^"]*)"/);
    expect(style?.[1]).toContain('width: 1440px; height: 960px');
  });

  it('resolves every relative href to a sibling file', () => {
    const relative = hrefs(html).filter(isRelative);
    expect(relative.length).toBeGreaterThan(0);
    for (const href of relative) {
      const path = href.split(/[?#]/)[0];
      expect(path, href).not.toContain('/');
      expect(existsSync(fileURLToPath(new URL(path, DESIGN_DIR))), href).toBe(true);
    }
  });

  it('has no href pointing at the uncommitted Evals artboard', () => {
    for (const href of hrefs(html)) {
      expect(href).not.toMatch(/DEvals/i);
    }
    expect(html).toContain('title="Evals is not part of kew"');
  });
});
